sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({api, helpers}) {
  const rows = id => ((api.data[id] || {}).results) || [];
  const v = (r, f) => (r[f] && r[f].value) || '';
  const count = (rs, f) => rs.reduce((m, r) => (m[v(r, f)] = (m[v(r, f)] || 0) + 1, m), {});
  const head = t => '<div style="display:flex;justify-content:space-between;align-items:center;padding-bottom:12px;margin-bottom:14px;border-bottom:1px solid #e3e7ea"><span style="font-size:16px;color:#2e3d49">' + t + '</span></div>';
  const leg = items => '<div style="display:flex;justify-content:center;gap:18px;flex-wrap:wrap;font-size:12px;color:#4a5a66;margin-top:12px">' + items.map(i => '<span style="display:inline-flex;align-items:center;gap:6px"><span style="width:10px;height:10px;background:' + i.c + ';display:inline-block"></span>' + i.l + '</span>').join('') + '</div>';
  const nice = m => m <= 4 ? 4 : m <= 8 ? 8 : m <= 10 ? 10 : Math.ceil(m / 5) * 5;
  const round = (items, center, pie) => {
    const tot = items.reduce((s, i) => s + i.n, 0);
    if (!tot) return '<div style="text-align:center;color:#6b7a85;font-size:13px;padding:40px 0">No data yet</div>';
    let acc = 0; const stops = items.filter(i => i.n).map(i => { const a = acc / tot * 100; acc += i.n; return i.c + ' ' + a + '% ' + (acc / tot * 100) + '%'; }).join(', ');
    const hole = pie ? '' : '<div style="grid-area:1/1;align-self:center;justify-self:center;width:96px;height:96px;border-radius:50%;background:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center"><span style="font-size:24px;color:#1d2b36;line-height:1.1">' + center[0] + '</span><span style="font-size:11px;color:#6b7a85">' + center[1] + '</span></div>';
    const chart = '<div style="display:grid;width:160px;height:160px;flex:none"><div style="grid-area:1/1;width:160px;height:160px;border-radius:50%;background:conic-gradient(' + stops + ')"></div>' + hole + '</div>';
    const list = '<div style="flex:1;min-width:170px;display:flex;flex-direction:column;gap:10px">' + items.map(i => '<div style="display:flex;align-items:center;gap:8px;font-size:13px;color:#2e3d49"><span style="width:10px;height:10px;background:' + i.c + ';display:inline-block;flex:none"></span><span style="flex:1">' + i.l + '</span><b style="font-weight:600">' + i.n + '</b><span style="width:40px;text-align:right;color:#6b7a85">' + Math.round(i.n / tot * 100) + '%</span></div>').join('') + '</div>';
    return '<div style="display:flex;align-items:center;gap:32px;flex-wrap:wrap;justify-content:center;padding:4px 0">' + chart + list + '</div>';
  };
  const colChart = items => {
    const max = nice(Math.max.apply(null, items.map(i => i.n).concat([1]))); const H = 150;
    const axis = '<div style="display:flex;flex-direction:column;justify-content:space-between;height:' + H + 'px;font-size:10px;color:#6b7a85;text-align:right;padding-right:6px">' + [4,3,2,1,0].map(k => '<span style="line-height:0">' + Math.round(max * k / 4) + '</span>').join('') + '</div>';
    const cols = items.map(i => '<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:' + H + 'px"><div style="width:60%;max-width:80px;height:' + Math.round(i.n / max * H) + 'px;background:' + i.c + ';display:flex;align-items:center;justify-content:center">' + (i.n ? '<span style="background:#c9d6e3;color:#1d2b36;font-size:10px;padding:1px 5px">' + i.n + '</span>' : '') + '</div></div>').join('');
    const labels = '<div style="display:flex;margin-left:28px">' + items.map(i => '<span style="flex:1;text-align:center;font-size:11px;color:#4a5a66;padding-top:6px">' + i.l + '</span>').join('') + '</div>';
    return '<div style="display:flex"><div style="width:28px">' + axis + '</div><div style="flex:1;display:flex;gap:8px;border-bottom:1px solid #9aa5ad;background:repeating-linear-gradient(to top,#e3e7ea 0 1px,transparent 1px ' + (H / 4) + 'px)">' + cols + '</div></div>' + labels;
  };
  const hbar = items => {
    const max = nice(Math.max.apply(null, items.map(i => i.n).concat([1])));
    const rowsHtml = items.map(i => '<div style="display:flex;align-items:center;height:40px"><span style="width:130px;flex:none;text-align:right;padding-right:10px;font-size:12px;color:#4a5a66">' + i.l + '</span><div style="flex:1;height:40px;display:flex;align-items:center;border-left:1px solid #9aa5ad;background:repeating-linear-gradient(90deg,#e3e7ea 0 1px,transparent 1px 25%)"><div style="height:24px;width:' + (i.n / max * 100) + '%;background:' + i.c + '"></div>' + (i.n ? '<span style="font-size:11px;color:#1d2b36;padding-left:6px">' + i.n + '</span>' : '') + '</div></div>').join('');
    const ticks = '<div style="display:flex;margin-left:130px;font-size:10px;color:#6b7a85;padding-top:4px">' + [0,1,2,3,4].map(k => '<span style="flex:' + (k ? 1 : 0) + ';text-align:right">' + Math.round(max * k / 4) + '</span>').join('') + '</div>';
    return rowsHtml + ticks;
  };
  const c = count(rows('gn_applicants'), 'state');
  const order = [['new','New','#93c1f0'],['ready_for_review','Ready for Review','#5aa0e6'],['review_in_progress','Review in Progress','#2f7ed8'],['review_completed','Review Completed','#0b4f9c'],['award_pending','Award Pending','#2f7ed8'],['award_acknowledged','Award Acknowledged','#0b4f9c'],['project_in_progress','Project in Progress','#0a2e5c'],['project_completed','Project Completed','#0a2e5c']];
  const items = order.filter(o => c[o[0]]).map(o => ({l:o[1], n:c[o[0]], c:o[2]}));
  return head('Applicant pipeline') + colChart(items) + leg([{l:'Service Applicants', c:'#0b4f9c'}]);
}
